  remove(id) { S.slip = S.slip.filter((x) => String(x.id) !== String(id)); this._save(); },
  update(id, val) { const x = S.slip.find((y) => String(y.id) === String(id)); if (!x) return false; x.val = Number(val) || x.val; this._save(); return true; },
  updateAll(map) { let n = 0; S.slip.forEach((x) => { if (map[x.id] != null && map[x.id] !== x.val) { x.val = Number(map[x.id]); n++; } }); if (n) this._save(); return n; },
