    if (ex) { Object.assign(ex, { onClose: o.onClose, dismiss: o.dismiss }); this.stack.splice(this.stack.indexOf(ex), 1); this.stack.push(ex); this.inert(); return ex; }
    const ent = { type, wrap, opener: d.activeElement, onClose: o.onClose, dismiss: o.dismiss == null ? true : o.dismiss };
    clearTimeout(wrap._t);
    wrap.hidden = false; void wrap.offsetWidth; wrap.classList.add('on');
