let popOpen = false;
const menu = {
  open(ev) {
    if (innerWidth < 1024) {
      sheet.open(menuHtml(), { title: S.user ? 'Tu cuenta' : 'Menú', size: S.user ? 'tall' : 'auto' });
      setExp(true);
      const e = overlays.top(); if (e) { const prev = e.onClose; e.onClose = (r) => { setExp(false); if (prev) prev(r); }; }
      return;
    }
    const p = $('#acct'); p.innerHTML = menuHtml(); p.hidden = false; popOpen = true; setExp(true);
    // aberto pelo teclado (Enter/Espaço: detail 0) → foco no 1.º item; pelo clique → foco no próprio painel, sem quadro em volta do saldo (Rodada 2 · q11)
    const kb = !ev || ev.detail === 0, f = kb ? $('a, button', p) : p;
    if (!kb) p.tabIndex = -1;
    if (f) f.focus({ preventScroll: true });
  },
  close() {
    if (!popOpen) return;
    const p = $('#acct'); p.hidden = true; popOpen = false; setExp(false);
  },
  toggle(ev) { if (popOpen) { this.close(); const a = $('[data-av]'); if (a) a.focus(); } else this.open(ev); },
  get isOpen() { return popOpen; },
};
function setExp(v) { $$('[data-act="menu"]').forEach((b) => b.setAttribute('aria-expanded', String(v))); }

