/* ---------- abas e chips ---------- */
function tabSel(t, focus) {
  const list = t.closest('[role="tablist"]'); if (!list) return;
  const all = $$('[role="tab"]', list);
  all.forEach((x) => {
    const onn = x === t; x.setAttribute('aria-selected', String(onn)); x.tabIndex = onn ? 0 : -1;
    const pid = x.getAttribute('aria-controls'); const p = pid && d.getElementById(pid); if (p) p.hidden = !onn;
  });
  if (focus) t.focus();
  emit('tab', { grupo: list.dataset.tabs, i: all.indexOf(t), label: t.textContent.trim(), el: t });
}
function chipSel(t) {
  const g = t.closest('[data-chips]'); if (!g) return;
  const multi = g.hasAttribute('data-multi');
  const all = $$('[data-chip]', g);
  let onn;
  if (multi) { onn = t.getAttribute('aria-pressed') !== 'true'; t.setAttribute('aria-pressed', String(onn)); }
  else { onn = true; all.forEach((x) => x.setAttribute('aria-pressed', String(x === t))); }
  emit('chip', { grupo: g.dataset.chips, i: all.indexOf(t), label: t.textContent.trim(), el: t, on: onn });
}

/* ---------- delegação única ---------- */
const SEL = '[data-close],[data-login],[data-go],[data-act],[data-odd],[data-tab],[data-chip],[data-fav],[data-scroll],[data-toast],[data-sheet],[role="switch"]';
function act(t, ev) {
  const ds = t.dataset;
  if (t.getAttribute('role') === 'switch' && !ds.act) { t.setAttribute('aria-checked', String(t.getAttribute('aria-checked') !== 'true')); emit('sw', { el: t, on: t.getAttribute('aria-checked') === 'true' }); return; }
  if (ds.login) { LG().open({ mode: ds.login }); return; }
  if (ds.go != null) { go(ds.go || 'inicio', { anchor: ds.anchor }); return; }
  if (ds.act) {
    if (t.getAttribute('role') === 'switch') t.setAttribute('aria-checked', String(t.getAttribute('aria-checked') !== 'true'));
    const f = ACT[ds.act]; if (f) f(t, ev); else console.warn('ACT sin registrar:', ds.act); return;
  }
  if (ds.odd != null) { slip.toggle({ id: ds.odd, desc: ds.desc, val: +ds.val, mkt: ds.mkt }); return; }
  if (ds.tab != null) { tabSel(t); return; }
  if (ds.chip != null) { chipSel(t); return; }
  if (ds.fav) { fav.toggle(ds.fav); return; }
  if (ds.scroll) { railScroll(ds.scroll, +ds.dir || 1); return; }
  if (ds.toast) { toast(ds.toast); return; }
  if (ds.sheet) { openSheet(ds.sheet, t); }
}
/* pausa ativa: jogar, apostar e depositar ficam bloqueados (retirar, limites e ayuda seguem livres) */
function enPausa() { const p = S.lim && S.lim.pausa; return !!(S.user && p && (p.hasta == null || p.hasta > Date.now())); }
function bloqueaPausa(t) {
  if (!enPausa()) return false;
  const ds = t.dataset || {};
  const jogo = ds.sheet === 'juego' || ds.odd != null || ds.go === 'deposito' || (ds.act && /^(playGo|spApostar|hmTorneo)$/.test(ds.act));
  if (!jogo) return false;
  // Rodada 1 · q8: "Tu pausa termina el 25/10 a las 11:51." (dd/mm e 24 h, igual ao resto do site)
  const p = S.lim.pausa, h = p.hasta ? new Date(p.hasta) : null;
  const fim = h ? `Tu pausa termina el ${pad2(h.getDate())}/${pad2(h.getMonth() + 1)} a las ${pad2(h.getHours())}:${pad2(h.getMinutes())}. ` : '';
  sheet.open(`<div class="pz"><p class="etq-s luz">Juego responsable</p><p class="pz-t">Tu pausa sigue activa</p><p class="pz-s">${fim}Mientras tanto podés retirar tu saldo, ver tus límites o hablar con alguien.</p></div>` +
    `<div class="gs-acts">${btn('Retirar tu saldo', { kind: 'pri', size: 'l', block: true, href: '#retiro', attrs: 'data-go="retiro"' })}${btn('Ver tus límites', { kind: 'sec', size: 'l', block: true, href: '#limites', attrs: 'data-go="limites"' })}${btn('Hablar con alguien', { kind: 'ghost', size: 'l', block: true, attrs: 'data-sheet="soporte"' })}</div>`, { title: 'Pausa activa' });
  return true;
}
d.addEventListener('click', (ev) => {
  // menu popover: clique fora fecha
  if (popOpen && !ev.target.closest('#acct') && !ev.target.closest('[data-act="menu"]')) menu.close();
  $$('.sel-l:not([hidden])').forEach((l) => { if (!l.parentElement.contains(ev.target)) { l.hidden = true; const b = l.parentElement.querySelector('.sel-b'); if (b) b.setAttribute('aria-expanded', 'false'); } });
  const t = ev.target.closest(SEL);
  if (!t || t.tagName === 'FORM') return; // form[data-act] é só para submit
  if (t.closest('form') && t.type === 'submit' && !t.dataset.act) return;
  if (t.tagName === 'A') ev.preventDefault();
  if (t.hasAttribute('data-close')) { overlays.closeTop(t.dataset.close || 'btn'); return; }
  if (bloqueaPausa(t)) { ev.preventDefault(); return; }
  if (t.hasAttribute('data-auth') && !session.is()) {
    const reason = t.dataset.auth && t.dataset.auth.length > 1 ? t.dataset.auth : undefined;
    requireLogin(() => act(t.isConnected ? t : t, ev), { reason });
    return;
  }
  act(t, ev);
});
d.addEventListener('submit', (ev) => {
  const f = ev.target; const name = f.dataset && f.dataset.act;
  if (!name) return;
  ev.preventDefault();
  const run = () => { const fn = ACT[name]; if (fn) fn(f, ev); else console.warn('ACT sin registrar:', name); };
  if (f.hasAttribute('data-auth') && !session.is()) requireLogin(run, { reason: f.dataset.auth || undefined }); else run();
});
d.addEventListener('input', (ev) => {
  const t = ev.target.closest('[data-input]'); if (!t) return;
  const fn = ACT[t.dataset.input]; if (fn) fn(t, ev);
});
d.addEventListener('keydown', (ev) => {
  const t = ev.target;
  if (ev.key === 'Escape') {
    if (overlays.stack.length) { ev.preventDefault(); overlays.closeTop('esc'); return; }
    if (popOpen) { menu.close(); const a = $('[data-av]'); if (a) a.focus(); return; }
    const sl = $('.sel-l:not([hidden])'); if (sl) { sl.hidden = true; const b = sl.parentElement.querySelector('.sel-b'); b.setAttribute('aria-expanded', 'false'); b.focus(); }
    return;
  }
  if (t.getAttribute && t.getAttribute('role') === 'tab' && ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(ev.key)) {
    const all = $$('[role="tab"]', t.closest('[role="tablist"]'));
    let i = all.indexOf(t);
    i = ev.key === 'Home' ? 0 : ev.key === 'End' ? all.length - 1 : (i + (ev.key === 'ArrowRight' ? 1 : -1) + all.length) % all.length;
    ev.preventDefault(); tabSel(all[i], true); return;
  }
  if (ev.key === 'Tab') {
    const top = overlays.top(); const panel = top ? top.wrap.lastElementChild : (popOpen ? $('#acct') : null);
    if (!panel) return;
    const f = $$('a[href],button:not([disabled]),input:not([disabled]):not([type=hidden]),select,textarea,[tabindex]:not([tabindex="-1"])', panel).filter((x) => x.offsetParent !== null || x.getClientRects().length);
    if (!f.length) return;
    if (popOpen && !top) { if ((!ev.shiftKey && t === f[f.length - 1]) || (ev.shiftKey && t === f[0])) menu.close(); return; }
    if (ev.shiftKey && (t === f[0] || !panel.contains(t))) { ev.preventDefault(); f[f.length - 1].focus(); }
    else if (!ev.shiftKey && (t === f[f.length - 1] || !panel.contains(t))) { ev.preventDefault(); f[0].focus(); }
  }
});

/* ---------- rolagem e redimensionamento (uma escuta de cada) ---------- */
const BPS = [0, 600, 768, 1024, 1280, 1440, 1600, 1760, 1920];
const bpOf = (w) => BPS.filter((b) => w >= b).pop();
S.bp = bpOf(innerWidth);
let rafS = 0, lastY = scrollY, rafR = 0;
addEventListener('scroll', () => {
  if (rafS) return;
  rafS = requestAnimationFrame(() => {
    rafS = 0; const y = scrollY;
    if (!RM.matches && innerWidth < 1024 && !overlays.stack.length) {
      if (y > lastY + 6 && y > 160) root.classList.add('nav-off');
      else if (y < lastY - 6) root.classList.remove('nav-off');
    }
    lastY = y;
  });
}, { passive: true });
d.addEventListener('scroll', (e) => { if (e.target !== d && e.target.classList && e.target.classList.contains('rail')) { cancelAnimationFrame(rafR); rafR = requestAnimationFrame(updateRails); } }, { passive: true, capture: true });
let rafZ = 0;
addEventListener('resize', () => {
  if (rafZ) return;
  rafZ = requestAnimationFrame(() => {
    rafZ = 0; const b = bpOf(innerWidth);
    if (b !== S.bp) {
      const was = S.bp; S.bp = b;
      if ((was < 1024) !== (b < 1024)) { menu.close(); if (sheet.isOpen() && $('#sheet .acct')) sheet.close(); }
      emit('bp', { bp: b, prev: was });
    }
    updateRails();
  });
}, { passive: true });

