/* ---------- Patrón 01 gerado (mosaico de retas e círculos, manual p30) ---------- */
const PAT = ['#C0E3F8', '#62B3E4', '#1C1D24'];
function rng(seed) { let a = seed >>> 0; return () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
function mosaico(cols = 8, rows = 2, seed = 1, o = {}) {
  const r = rng(seed * 9973 + cols * 31 + rows), pal = o.pal || PAT, out = [];
  const pick = (ex) => { let c; do { const x = r(); c = x < .48 ? pal[0] : x < .8 ? pal[1] : pal[2]; } while (c === ex); return c; };
  for (let y = 0; y < rows; y++) for (let x = 0; x < cols; x++) {
    const bg = pick(), fg = pick(bg), k = r();
    out.push(`<rect x="${x}" y="${y}" width="1.01" height="1.01" fill="${bg}"/>`);
    if (k < .34) { // semicírculo apoiado num lado
      const sd = Math.floor(r() * 4);
      const d = [`M${x} ${y}A.5 .5 0 0 0 ${x + 1} ${y}Z`, `M${x + 1} ${y}A.5 .5 0 0 0 ${x + 1} ${y + 1}Z`, `M${x} ${y + 1}A.5 .5 0 0 1 ${x + 1} ${y + 1}Z`, `M${x} ${y}A.5 .5 0 0 1 ${x} ${y + 1}Z`][sd];
      out.push(`<path d="${d}" fill="${fg}"/>`);
    } else if (k < .6) { // quarto de círculo num canto
      const c = Math.floor(r() * 4);
      const d = [`M${x} ${y}h1A1 1 0 0 1 ${x} ${y + 1}Z`, `M${x + 1} ${y}v1A1 1 0 0 1 ${x} ${y}Z`, `M${x + 1} ${y + 1}h-1A1 1 0 0 1 ${x + 1} ${y}Z`, `M${x} ${y + 1}v-1A1 1 0 0 1 ${x + 1} ${y + 1}Z`][c];
      out.push(`<path d="${d}" fill="${fg}"/>`);
    } else if (k < .78) out.push(`<circle cx="${x + .5}" cy="${y + .5}" r=".5" fill="${fg}"/>`);
  }
  return `<svg viewBox="0 0 ${cols} ${rows}" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false">${out.join('')}</svg>`;
}
function paintMosaicos(rootEl = d) {
  $$('[data-mosaico]', rootEl).forEach((el) => {
    if (el.firstElementChild) return;
    const m = /^(\d+)x(\d+)(?::(\d+))?$/.exec(el.dataset.mosaico || '') || [0, 8, 2, 1];
    el.innerHTML = mosaico(+m[1], +m[2], +(m[3] || 1));
  });
}

/* ---------- arranque do core (DOM já parseado: scripts defer) ---------- */
function mountChrome() {
  const f = $('#ftr'); if (f) { f.innerHTML = ftrHtml(); lazy(f); }
  paintMosaicos(d); paintChrome(); paintSlip();
}
mountChrome();

