const LZ = (h) => String(h).replace(/<img class="pic([^"]*)" src="/g, '<img class="pic$1" data-src="');
function lazy(rootEl) {
  const load = (img) => { const s = img.getAttribute('data-src'); if (s) { img.src = s; img.removeAttribute('data-src'); } };
  const imgs = $$('img[data-src]', rootEl);
  if (!imgs.length) return;
  if (!('IntersectionObserver' in window)) { imgs.forEach(load); return; }
  const hs = []; let idle = false; const act = [];
  const watch = (rail, m) => {
    const h = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { load(e.target); h.unobserve(e.target); } }), { root: rail, rootMargin: m });
    $$('img[data-src]', rail).forEach((i) => h.observe(i)); hs.push(h);
  };
  const hz = (rail) => { act.push(rail); watch(rail, '0px 50% 0px 0px'); if (idle && !rail.dataset.lz) watch(rail, '0px 100% 0px 0px'); };
  later(2500, () => { idle = true; act.forEach((r) => { if (!r.dataset.lz) watch(r, '0px 100% 0px 0px'); }); });
  const v = new IntersectionObserver((es) => es.forEach((e) => {
    if (!e.isIntersecting) return;
    v.unobserve(e.target);
    if (e.target.tagName === 'IMG') load(e.target); else hz(e.target);
  }), { rootMargin: '0px 0px 160px 0px' });
  const scrollers = $$('.rail, .h-bn-t', rootEl).filter((r) => $('img[data-src]', r));
  scrollers.forEach((r) => v.observe(r));
  imgs.filter((i) => !i.closest('.rail, .h-bn-t')).forEach((i) => v.observe(i));
  life(() => { v.disconnect(); hs.forEach((h) => h.disconnect()); });
}
