    on('tab', (d) => { if (d.grupo !== 'cs-t') return; CS.tab = d.i; CS.page = 1; paintCasino(); });
    on('fav', () => { if (CASINO_CHIPS[CS.f].f === 'fav') paintCasino(); });
    on('bp', () => paintCasino());
