/* Actualizar: revela el movimiento del sistema (guionado, una vez por ámbito). Nada cambia solo. */
const MOVES = {
  e1: [['e1-res-0', 0.95], ['e1-res-2', 1.07], ['e1-ou-2', 1.05], ['susp', 'e1-ng']],
  dep: [['e1-res-0', 0.95], ['e1-res-2', 1.07], ['e7-res-2', 1.04]],
  aum: [['bst-b2', 0.96], ['bst-b8', 1.03]],
};
ACT.spUpd = (b) => {
  const sc = b.dataset.scope;
  let list = MOVES[sc];
  if (!list && EVK[sc]) list = [[`${sc}-res-0`, 1.04], [`${sc}-res-${EVK[sc].o.length - 1}`, 0.96]];
  busy(b, true);
  setTimeout(() => {
    busy(b, false);
    const t = hm(); $$('[data-sp-stamp]').forEach((x) => { x.textContent = t; }); EST.stamp[sc] = t;
    if (UPD[sc] || !list) { toast('Las cuotas ya estaban al día.'); return; }
    UPD[sc] = 1;
    let n = 0;
    list.forEach(([id, f]) => {
      if (id === 'susp') { SUSP.add(f); return; }
      const old = cur(id); if (old == null) return; const nv = r2(old * f); SYS[id] = nv; MOV[id] = nv > old ? 'up' : 'dn'; n++;
    });
    save(); repaintOdds(); toast(n > 1 ? `Listo: cambiaron ${n} cuotas.` : 'Listo: cambió una cuota.', { kind: 'ok' });
    setTimeout(() => { Object.keys(MOV).forEach((k) => delete MOV[k]); $$('.sp-mv').forEach((x) => x.remove()); }, 3000);
    emit('slip', { items: S.slip.slice(), odds: true });
  }, 500);
};
function repaintOdds() {
  const e = EVK[EST.cur];
  const m = $('#sp-mks'); if (m && e) m.innerHTML = mksHtml(e);
  const eb = $('#sp-evb'); if (eb && e) eb.outerHTML = evBoosts(e);
  const g = $('#sp-aum'); if (g) g.innerHTML = aumList();
  const li = $('#sp-list'); if (li) li.innerHTML = listHtml();
  /* resto de la pantalla (destacados, cartones de la Inicio): solo valor + flecha */
  Object.keys(MOV).forEach((id) => $$(`[data-odd="${CSS.escape(id)}"]`).forEach((x) => {
    const v = $('.odd-v', x); if (v) v.textContent = odd(cur(id)); x.dataset.val = cur(id);
    if (!$('.sp-mv', x) && v) v.insertAdjacentHTML('beforebegin', mv(id));
  }));
  paintSlip();
}

