/* =========================================================== JUEGO RESPONSABLE (Cumbia r2-d4 + Diez r2-d4 B: Depósito → Pérdida → Tiempo → Recordatorios → Revisar)
   regra de carência: bajar/poner vale na hora; subir/sacar só depois do prazo [24 h — por confirmar] */
const PER = ['dia', 'sem', 'mes'], PERL = ['Por día', 'Por semana', 'Por mes'], PERS = { dia: 'por día', sem: 'por semana', mes: 'por mes' }, PADJ = { dia: 'diario', sem: 'semanal', mes: 'mensual' };
/* montos rápidos dos limites em escala real (Rodada 1 · q11) */
const QV = { dep: { dia: [25000, 50000, 100000, 250000], sem: [100000, 250000, 500000, 1000000], mes: [250000, 500000, 1000000, 2500000] }, perda: { dia: [10000, 25000, 50000, 100000], sem: [50000, 100000, 250000, 500000], mes: [100000, 250000, 500000, 1000000] } };
const TV = [30, 60, 120, 180, 240, null], RV = [15, 30, 60];
const tvl = (m) => (m == null ? 'Sin límite' : hm(m));
const PLAZO = '[24 horas — por confirmar]';
const RG = { step: 0, per: 'dia', perP: 'dia', rem: { on: true, cada: 60, gasto: false }, pend: [], excl: null, d: null, nova: false,
  hist: [{ at: Date.now() - 12 * H24, t: 'Límite de depósito diario', d: `Sin límite → ${money(VAL.lim.dia)}`, s: 'Valió en el momento' }, { at: Date.now() - 31 * H24, t: 'Recordatorio de tiempo', d: 'Apagado → Cada 60 min', s: 'Valió en el momento' }] };
/* Rodada 2 · d4 B (ajuste): a pérdida ganha passo próprio e cada passo começa com o interruptor desligado; período, montos e
   frequência só aparecem quando a pessoa liga. Só começa ligado o que a conta já tem ativo (desligar = sacar, com o prazo). */
