const has = (o) => PER.some((k) => o[k] != null);
const draft = () => ({ dep: Object.assign({}, S.lim.dep), depOn: has(S.lim.dep), perda: Object.assign({}, S.lim.perda), pOn: has(S.lim.perda),
  tempo: S.lim.tempo.min, tOn: S.lim.tempo.min != null, rem: Object.assign({}, RG.rem) });
/* conta nova (q1): sem aviso ligado e sem histórico de exemplo */
function rgAcc() { if (newAcc() && !RG.nova) { RG.nova = true; RG.rem = { on: false, cada: null, gasto: false }; RG.hist = []; RG.pend = []; } }
const pendOf = (t, p) => RG.pend.find((x) => x.t === t && x.p === p);
