function grpErrSet(id, msg) { const e = $('#' + id); if (!e) return; e.textContent = msg; e.hidden = !msg; }
/* interruptores dos passos: ligar devolve o que a conta já tem (ou nada escolhido); desligar = sem límite */
ACT.ctLimOn = (b) => {
  const D = RG.d, k = b.dataset.k, onn = b.getAttribute('aria-checked') === 'true';
  if (k === 'dep') { D.depOn = onn; D.dep = Object.assign({}, S.lim.dep); RG.per = PER.find((x) => S.lim.dep[x]) || 'dia'; }
  if (k === 'perda') { D.pOn = onn; D.perda = Object.assign({}, S.lim.perda); RG.perP = PER.find((x) => S.lim.perda[x]) || 'dia'; }
  if (k === 'tempo') { D.tOn = onn; D.tempo = S.lim.tempo.min; }
  rgPaint(); const s = $(`[data-act="ctLimOn"][data-k="${k}"]`); if (s) s.focus();
};
ACT.ctRem = (b) => {
  const k = b.dataset.k, D = RG.d; D.rem[k] = b.getAttribute('aria-checked') === 'true';
  if (k === 'on') {
    if (D.rem.on) { D.rem.cada = RG.rem.on ? RG.rem.cada : null; D.rem.gasto = RG.rem.on ? RG.rem.gasto : false; }
    rgPaint(); const s = $('[data-act="ctRem"][data-k="on"]'); if (s) s.focus();
  }
};
ACT.ctRgGo = (b) => {
  RG.step = +b.dataset.s; rgPaint(true);
  if (b.hasAttribute('data-jump')) { const w = $('#ct-wzs'); if (w) w.scrollIntoView({ block: 'start', behavior: smooth() }); }
};
/* ligado sem escolher = pede o monto (ou que apague o interruptor) e não avança */
function rgCheck() {
  const D = RG.d, i = RG.step, MSG = 'Elegí un monto o apagá el límite.';
  const inp = $(i === 1 ? '#ct-limp' : '#ct-lim');
  if (inp && parseMoney(inp.value) > VAL.lim.max) { inp.focus(); return false; }
  if ((i === 0 && D.depOn && !has(D.dep)) || (i === 1 && D.pOn && !has(D.perda))) { if (inp) { fieldError(inp, MSG); inp.focus(); } return false; }
  if (i === 2 && D.tOn && D.tempo == null) { grpErrSet('ct-tm-e', 'Elegí un tiempo o apagá el límite.'); const c = $('[data-chips="ctt"] .chip'); if (c) c.focus(); return false; }
  if (i === 3 && D.rem.on && !D.rem.cada) { grpErrSet('ct-rem-e', 'Elegí cada cuánto o apagá el aviso.'); const c = $('[data-chips="ctrem"] .chip'); if (c) c.focus(); return false; }
  return true;
}
ACT.ctRgNext = () => {
  if (!rgCheck()) return;
  RG.step = Math.min(RVI, RG.step + 1); rgPaint(true);
  const w = $('#ct-wzs'); if (w && w.getBoundingClientRect().top < 0) w.scrollIntoView({ block: 'start', behavior: smooth() });
};
ACT.ctRgPrev = () => { RG.step = Math.max(0, RG.step - 1); rgPaint(true); };
ACT.ctRgKeep = () => { RG.d = draft(); RG.step = 0; rgPaint(true); toast('Descartaste los cambios. Tus límites siguen igual.'); };
ACT.ctRgSave = (b) => {
  const ch = rgChanges();
  if (!ch.length) { toast('Nada cambió en tus límites'); return; }
  busy(b, true, 'Guardando…');
  later(500, () => {
    const when = Date.now() + H24, dep = {}, perda = {};
    ch.forEach((c) => {
      if (c.t === 'rem') { RG.rem = Object.assign({}, RG.d.rem); RG.hist.unshift({ at: Date.now(), t: 'Recordatorio de tiempo', d: `${c.a} → ${c.b}`, s: 'Valió en el momento' }); return; }
      RG.pend = RG.pend.filter((x) => !(x.t === c.t && x.p === c.p));
      const down = cmpv(c.a, c.b) === 'dn';
      RG.hist.unshift({ at: Date.now(), t: c.l[0].toUpperCase() + c.l.slice(1), d: `${fmtV(c.t, c.a)} → ${fmtV(c.t, c.b)}`, s: down ? 'Valió en el momento' : `Vale desde el ${dm(when)}` });
      if (down) { if (c.t === 'tempo') lim.set('tempo', { min: c.b }); else (c.t === 'dep' ? dep : perda)[c.p] = c.b; }
      else RG.pend.push({ t: c.t, p: c.p, v: c.b, at: when });
    });
    if (Object.keys(dep).length) lim.set('dep', dep);
    if (Object.keys(perda).length) lim.set('perda', perda);
    const nP = ch.filter((c) => c.t !== 'rem' && cmpv(c.a, c.b) !== 'dn').length;
    RG.d = draft(); RG.step = 0; rgPaint();
    toast(nP ? `Límites guardados. ${nP > 1 ? 'Los aumentos valen' : 'El aumento vale'} desde el ${dm(when)} a las ${hh(when)}.` : 'Límites guardados. Ya valen.', { kind: 'ok', ms: 4200 });
    const c = $('#ct-lcs'); if (c) c.scrollIntoView({ block: 'center', behavior: smooth() });
  });
};
ACT.ctRgCancel = (b) => { RG.pend = RG.pend.filter((x) => !(x.t === b.dataset.t && x.p === b.dataset.p)); rgPaint(); toast('Aumento cancelado. Tu límite sigue igual.'); };
/* pausa: elegir → resumen → confirmar (sin invitación a volver a jugar) */
