  d2: { c: 0, t: '¿Con qué medios puedo depositar?', b: ['Transferencia (CBU, CVU o alias), billetera virtual y tarjeta de débito o de crédito. [Tarjeta de crédito según tu provincia — por confirmar]', 'Siempre desde cuentas a tu nombre.'], go: ['deposito', 'Ir a depositar'] },
  d3: { c: 0, t: '¿Hay un monto mínimo para depositar?', b: ['Sí. El mínimo lo ves en la pantalla de depósito, según el medio que elijas. [Montos mínimos — por confirmar]', 'Tu límite de depósito siempre manda: si llegaste a tu límite, el depósito no pasa.'] },
  r1: { c: 1, t: '¿Cómo sigo mi retiro?', b: ['En Billetera ves cada etapa de tu retiro:', ['Solicitado', 'En revisión', 'Aprobado', 'Acreditado'], 'Al final, tenés tu comprobante.'], go: ['billetera', 'Ir a Billetera'] },
