  credito: '<rect x="2.5" y="5" width="19" height="14" rx="2.5"/><rect x="5.5" y="8.5" width="4.5" height="3.5" rx="1"/><path d="M5.5 15.5h4M13 15.5h5.5"/>',
  dni: '<rect x="2.5" y="5" width="19" height="14" rx="2.5"/><circle cx="8.5" cy="11" r="2"/><path d="M5.5 16c.6-1.3 1.7-2 3-2s2.4.7 3 2M14 10h4.5M14 13.5h3"/>',
