// QR desenhado em SVG (determinístico, sem dados reais)
function qr(seed) {
  const N = 25, f = (x, y) => (x < 7 && y < 7) || (x > N - 8 && y < 7) || (x < 7 && y > N - 8);
  let p = '', s = seed;
  const rnd = () => { s = (s * 9301 + 49297) % 233280; return s / 233280; };
  for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) if (!f(x, y) && rnd() > .52) p += `M${x} ${y}h1v1h-1z`;
  const fin = (x, y) => `M${x} ${y}h7v7h-7zM${x + 1} ${y + 1}v5h5v-5zM${x + 2} ${y + 2}h3v3h-3z`;
  return `<svg class="dn-qr" viewBox="-2 -2 29 29" role="img" aria-label="Código QR de pago · ejemplo"><rect x="-2" y="-2" width="29" height="29" rx="2" fill="#FFFFFF"/><path fill="#121418" fill-rule="evenodd" d="${p}${fin(0, 0)}${fin(N - 7, 0)}${fin(0, N - 7)}"/></svg>`;
}
const cpRow = (k, v, lbl) => `<div class="dn-code"><span><span class="etq-s">${k}</span><code class="tnum">${v}</code></span>${btn('Copiar', { kind: 'sec', size: 's', icon: 'copiar', attrs: `data-act="ctCopy" data-copy="${esc(v.replace(/\s/g, ''))}" data-msg="${lbl} copiado" aria-label="Copiar ${lbl}"` })}</div>`;
