  if (ctx === 'sh') { sheet.close(); const b = $('#dn-mng'); if (b) b.innerHTML = srcBox(); return; }
  const box = ctx === 'dep' ? $('#dn-from') : $('#dn-accs');
  if (box) { box.innerHTML = ctx === 'dep' ? fromBox() : accList(); const r = box.querySelector(`input[value="${id}"]`); if (r) r.focus(); }
